package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonSubTypes.Type;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsontype.NamedType;
import com.fasterxml.jackson.databind.jsontype.SubtypeResolver;
import java.io.*;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Collections;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StdSubtypeResolver_collectAndResolveSubtypesByTypeId_TriageGen1Test {

    private StdSubtypeResolver resolver;
    private MapperConfig<?> mockConfig;
    private AnnotationIntrospector mockAi;
    private AnnotatedMember mockProperty;
    private JavaType mockBaseType;

    // Test hierarchy classes
    public static class Base {}
    public static class Sub extends Base {}
    public static class Unrelated {}

    // Class for testing AnnotationIntrospector branch
    @JsonSubTypes({
        @Type(value = Sub.class, name = "sub"),
        @Type(value = Unrelated.class, name = "unrelated")
    })
    public static class AnnotatedBase extends Base {}

    @Before
    public void setUp() {
        resolver = new StdSubtypeResolver();
        mockConfig = mock(MapperConfig.class);
        mockAi = mock(AnnotationIntrospector.class);
        mockProperty = mock(AnnotatedMember.class);
        mockBaseType = mock(JavaType.class);

        when(mockConfig.getAnnotationIntrospector()).thenReturn(mockAi);
        when(mockBaseType.getRawClass()).thenReturn(Base.class);
    }

    @Test
    public void testCollectSubtypes_OnlyHierarchy() {
        // Scenario: No annotations on property, no registered subtypes.
        // Only the base class itself should be processed via hierarchy.
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // The base class itself is added as a rootType in the method logic
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
    }

    @Test
    public void testCollectSubtypes_WithAnnotationIntrospector() {
        // Scenario: AnnotationIntrospector returns subtypes via the property.
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(new NamedType(Sub.class, "sub")));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        assertTrue("Should contain the subtype from annotations",
                result.stream().anyMatch(nt -> nt.getType().equals(Sub.class)));
    }

    @Test
    public void testCollectSubtypes_WithRegisteredSubtypes() {
        // Scenario: Subtypes are registered explicitly via registerSubtypes.
        // We register a valid subtype (Sub) and an invalid one (Unrelated) to test isAssignableFrom.
        resolver.registerSubtypes(Sub.class, Unrelated.class);
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // Sub is a subtype of Base, so it should be included
        assertTrue("Should contain the registered subtype",
                result.stream().anyMatch(nt -> nt.getType().equals(Sub.class)));
        // Unrelated is NOT a subtype of Base, so it should be filtered out by isAssignableFrom
        assertFalse("Should NOT contain the unrelated registered class",
                result.stream().anyMatch(nt -> nt.getType().equals(Unrelated.class)));
    }

    @Test
    public void testCollectSubtypes_FullPrecedenceChain() {
        // Scenario: All three sources are active.
        // 1. Hierarchy (Base)
        // 2. Annotations (Sub via property)
        // 3. Registered (Sub via explicit registration)

        resolver.registerSubtypes(Sub.class);
        when(mockAi.findSubtypes(mockProperty)).thenReturn(Collections.singletonList(new NamedType(Sub.class, "annotatedSub")));

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);

        assertNotNull(result);
        // Verify Base is present (from hierarchy)
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Base.class)));
        // Verify Sub is present (from annotations and registration)
        assertTrue(result.stream().anyMatch(nt -> nt.getType().equals(Sub.class)));
    }

    @Test
    public void testCollectSubtypes_WithNullRegisteredSubtypes() {
        // Note: In the real implementation, _registeredSubtypes is a field. 
        // Since we can't easily set it to null if it's initialized in constructor, 
        // we rely on the fact that if we don't call registerSubtypes, it might be empty or null depending on implementation.
        // If the code allows null, this tests the branch 'if (_registeredSubtypes != null)'.

        // This test assumes the default state of a new StdSubtypeResolver doesn't crash.
        when(mockAi.findSubtypes(mockProperty)).thenReturn(null);

        Collection<NamedType> result = resolver.collectAndResolveSubtypesByTypeId(mockConfig, mockProperty, mockBaseType);
        assertNotNull(result);
    }
}
